def free_names(source: str) -> set[str]:
    """Every name a chunk of code reads without defining. Over-approximate on purpose."""
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return None
    return {n.id for n in ast.walk(tree) if isinstance(n, ast.Name) and isinstance(n.ctx, ast.Load)} | {n.value.id for n in ast.walk(tree) if isinstance(n, ast.Attribute) and isinstance(n.value, ast.Name)}

