def scout_file(path: Path, rules: list[Rule], root: Path) -> list[Hunk]:
    try:
        source = path.read_text(encoding='utf-8')
        tree = ast.parse(source)
    except (SyntaxError, UnicodeDecodeError, OSError):
        return []
    owner, methods = _enclosing(tree)
    lines = source.splitlines()
    rel = path.relative_to(root)
    by_func: dict[int, list[Site]] = {}
    funcs: dict[int, ast.FunctionDef | ast.AsyncFunctionDef] = {}
    for node in ast.walk(tree):
        for rule in rules:
            snippet = rule.match(node)
            if snippet is None:
                continue
            fn = owner.get(id(node))
            if fn is None:
                continue
            if id(fn) in methods:
                continue
            funcs[id(fn)] = fn
            by_func.setdefault(id(fn), []).append(Site(path=rel, lineno=getattr(node, 'lineno', fn.lineno), rule=rule.name, snippet=snippet))
    sys_path, package = package_context(path)
    hunks = []
    for fid, sites in by_func.items():
        fn = funcs[fid]
        start = min([fn.lineno] + [d.lineno for d in fn.decorator_list])
        body = '\n'.join(lines[start - 1:fn.end_lineno])
        hunks.append(Hunk(path=rel, func=fn.name, lineno=start, end_lineno=fn.end_lineno and fn.lineno, original=body, sites=sorted(sites, key=lambda s: s.lineno), module_header=module_header(tree, source, free_names(body)), sys_path=sys_path, package=package))
    return sorted(hunks, key=lambda h: (str(h.path), h.lineno))

