        return {'status': 'differs', 'detail': f'{len(disagreements)} of {len(rows)} inputs disagree', 'witness': {'args': w['args'], 'old': f"{w['old'][0]}: {w['old'][1]}", 'new': f"{w['new'][0]}: {w['new'][1]}"}, 'tried': len(rows), 'exercised': len(exercised)}
